export const interlocutorBios = Object.fromEntries(entries.map(([name, text, url, reviewed = biographyReviewDate]) => [name, {
  text,
  sources: [{ url, label: "Biographical source" }],
  reviewed
}]));

export function biographyFor(person) {
  return interlocutorBios[typeof person === "string" ? person : person?.name] || null;
}

if (entries.length !== Object.keys(interlocutorBios).length) throw new Error("Duplicate interlocutor biography");

export function renderBiography(person, bio = biographyFor(person), headingLevel = 3) {
  if (!bio) return "";
  const escape = (value) => String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
  const heading = headingLevel === 2 ? "h2" : "h3";
  return `<section class="profile-biography" aria-label="About ${escape(person.name)}">
    <p class="eyebrow">Background</p>
    <${heading}>About ${escape(person.name)}</${heading}>
    <p>${escape(bio.text)}</p>
    <p class="profile-biography-source">${bio.sources.map(({ url }) => `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer" aria-label="Biographical source for ${escape(person.name)} (opens in a new tab)">Biographical source ↗</a>`).join(" · ")}</p>
  </section>`;
}
